    companion object {
        private val SPEC = """
-- Partition drift: a deliberately defective exhibit, not a pattern to copy.
--
-- The rejection-as-data idiom partitions an act on the state it collides with
-- ("applicable" / "refused") and hangs a rule off each side. This spec shows
-- why the *bare* spelling of that partition — the state predicate alone — is
-- broken: an act is data, it persists forever, so its partition membership is
-- re-evaluated every time the partitioning state changes. An act applied last
-- year drifts into the refused side the moment the state flips (recording a
-- spurious refusal — once per flip), and drifts back when it flips again
-- (re-firing a stale write that can clobber newer data).
--
-- Three spellings are here, over one domain. `BareEdit` carries the defect.
-- `SafeEdit` is the handled-once fix for a *persistent* act — the partition
-- scoped to *unhandled* acts, each side anchored by the outcome evidence its
-- own rule produces. `TransientEdit` is the language answer (README §4,
-- "Transient acts"): the act is an input to the state, not a member of it —
-- its partition evaluates exactly once, at its only commit, and drift has
-- nothing left to attach to.
--
-- The required checks accept the bare spelling — the hazard is semantic, not
-- an error — but the A4 advisory (checks.md) flags exactly the two bare-
-- partition rules: their trigger reads mutable state and their bodies never
-- disarm it. The handled-once family passes A4 because each rule disarms its
-- own side; the transient family is exempt by construction. The runtime
-- misbehavior (and both fixes behaving) is demonstrated by
-- `DriftDemonstrationTest` in this example's output module. Surfaced by
-- `payments.velle`'s address-change tests.

-- ── A note that can be locked ────────────────────────────────────────────────

-- The note's `locked` flag is system-maintained (the lock/unlock acts below
-- write it), so it lives on the rule-created record (V21); creating a note is
-- its own input act.
transient act CreateNote {
    title: text
    body: text
}

shape Note {
    title: text
    body: text
    locked: boolean initially false
}

rule MaterializeNote when CreateNote {
    Note from { title: title, body: body }
}

act LockNote {
    note: one Note
}

act UnlockNote {
    note: one Note
}

rule ApplyLock when LockNote {
    note.locked = true
}

rule ApplyUnlock when UnlockNote {
    note.locked = false
}

shape LockedNote = Note where locked

-- An admin rename deliberately ignores the lock — a second, lock-exempt
-- writer of `body`, here so the demonstration can put a newer value on the
-- note for the stale re-fire to clobber.
act RenameText {
    note: one Note
    newText: text
}

rule ApplyRename when RenameText {
    note.body = newText
}

-- ── The drift-exposed spelling (the defect on exhibit) ───────────────────────

-- The partition reads only the note's current state. Nothing anchors an act
-- to the moment it was handled, so every lock/unlock re-partitions every edit
-- ever committed:
--   lock   → every previously applied edit enters RefusedBareEdit
--            (a spurious refusal is recorded for each, per lock)
--   unlock → every one of them re-enters ApplicableBareEdit
--            (the rule re-fires, re-writing body text that was already superseded)
act BareEdit {
    note: one Note
    newText: text
}

shape ApplicableBareEdit = BareEdit where note is not LockedNote
shape RefusedBareEdit    = BareEdit where note is LockedNote

rule ApplyBareEdit when ApplicableBareEdit {
    note.body = newText
}

shape BareEditRefusal {
    edit: one BareEdit
    refusedOn: DateTime
}

rule RefuseBareEdit when RefusedBareEdit {
    BareEditRefusal from { edit: this, refusedOn: now }
}

-- ── The handled-once spelling (the fix) ──────────────────────────────────────

-- Each edit is handled exactly once, at its own commit: the outcome evidence
-- (application or refusal) removes it from the partition forever, so later
-- state changes re-partition nothing. Each rule's body produces the evidence
-- that disarms its own side — the disarm proof, doing double duty as the
-- anchor.
--
-- (This family edits `title`, not `body`. If it shared `body` with BareEdit,
-- v0's one-writer check would refuse the spec — a lock flip is one commit
-- that can drift BOTH families' acts into applicability, two writers at once.
-- That diagnostic is the drift hazard leaking out sideways; with disjoint
-- fields, the hazard is fully silent, which is what this exhibit shows.)
act SafeEdit {
    note: one Note
    newTitle: text
}

shape EditApplication {
    edit: one SafeEdit
    appliedOn: DateTime
}

shape EditRefusal {
    edit: one SafeEdit
    reason: text
    refusedOn: DateTime
}

shape UnhandledSafeEdit = SafeEdit where
    not exists EditApplication for this and not exists EditRefusal for this

shape ApplicableSafeEdit = UnhandledSafeEdit where note is not LockedNote
shape RefusedSafeEdit    = UnhandledSafeEdit where note is LockedNote

rule ApplySafeEdit when ApplicableSafeEdit {
    note.title = newTitle
    EditApplication from { edit: this, appliedOn: now }
}

rule RefuseSafeEdit when RefusedSafeEdit {
    EditRefusal from { edit: this, reason: "note is locked", refusedOn: now }
}

-- ── The transient spelling (the language answer) ─────────────────────────────

-- The act is an input to the state, not a member of it: its partition is
-- evaluated exactly once, at its only commit, so there is nothing for a later
-- lock flip to re-partition — no anchor apparatus needed at all. The refusal
-- copies the payload it wants to report (a transient act cannot be
-- referenced), and the complement pair of conditions is what proves every
-- edit gets a response (V18).
-- This family edits the note's `title`, like SafeEdit — compare the two:
-- same behavior, and the transient spelling needs no Unhandled scaffolding.
transient act TransientEdit {
    note: one Note
    newTitle: text
}

shape ApplicableTransientEdit = TransientEdit where note is not LockedNote
shape RefusedTransientEdit    = TransientEdit where note is LockedNote

rule ApplyTransientEdit when ApplicableTransientEdit {
    note.title = newTitle
}

shape TransientEditRefusal {
    note: one Note
    requestedTitle: text
    reason: text
    refusedOn: DateTime
}

rule RefuseTransientEdit when RefusedTransientEdit {
    TransientEditRefusal from { note: note, requestedTitle: newTitle, reason: "note is locked", refusedOn: now }
}
"""
    }
}

// ── the shapes as Kotlin data classes: what a query returns (README §22; OQ51 R5) ──
// References are typed handles (views); navigating one is a further read.

data class Note(
    override val id: Long,
    val title: String,
    val body: String,
    val locked: Boolean,
    val lockNotes: List<PartitionDriftSystem.LockNoteView>,
    val unlockNotes: List<PartitionDriftSystem.UnlockNoteView>,
    val renameTexts: List<PartitionDriftSystem.RenameTextView>,
    val bareEdits: List<PartitionDriftSystem.BareEditView>,
    val safeEdits: List<PartitionDriftSystem.SafeEditView>,
    val transientEditRefusals: List<PartitionDriftSystem.TransientEditRefusalView>,
) : View

data class LockNote(
    override val id: Long,
    val note: PartitionDriftSystem.NoteView,
) : View

data class UnlockNote(
    override val id: Long,
    val note: PartitionDriftSystem.NoteView,
) : View

data class RenameText(
