    fun isApplicableSafeEdit(): Expr = isA("ApplicableSafeEdit")
    fun isRefusedSafeEdit(): Expr = isA("RefusedSafeEdit")
}

class EditApplicationFields(path: List<String> = emptyList()) : Fields(path) {
